 void release(const Json& meta){for(unsigned owner:meta.value("release",std::vector<unsigned>{})){for(auto it=buffers.begin();it!=buffers.end();)if(it->second.owner==owner)it=buffers.erase(it);else ++it;for(auto it=textures.begin();it!=textures.end();)if(it->second.owner==owner){recycled.push_back(it->second.descriptor);it=textures.erase(it);}else ++it;}}
