public:
 MaterialDevice(HWND hwnd,const wchar_t* path):window(hwnd),folder(path){thread=std::thread([this]{run();});}
 ~MaterialDevice(){{std::lock_guard<std::mutex> lock(mutex);stopping=true;}changed.notify_one();if(thread.joinable())thread.join();if(constants&&constantData)constants->Unmap(0,nullptr);if(event)CloseHandle(event);}
